 applyB:[['Customer: Order chicken and juice.','Chicken with rice and orange juice, please.'],['Server: State the total for that order.','$15, please.'],['Customer: Ask to change chicken to a bean sandwich.','Could I have the bean sandwich instead, please?'],['Server: Confirm the new total with juice.','A bean sandwich and orange juice: $10.'],['Customer: Check and pay the bill.','The sandwich and juice are $10. Here you are. Thank you.']],
